arguments.file_text:
namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Spaghetti Carbonara", Category = "Pasta", Ingredients = "Spaghetti, eggs, pancetta, parmesan, black pepper", Steps = "1. Cook pasta\n2. Fry pancetta\n3. Mix eggs and cheese\n4. Combine all with pasta water", TotalRating = 14, RatingCount = 3 },
        new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Curry", Ingredients = "Chicken thighs, yogurt, tomato sauce, garam masala, cream", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill chicken\n3. Simmer in tomato-cream sauce", TotalRating = 9, RatingCount = 2 },
        new() { Id = 3, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce, croutons, parmesan, Caesar dressing, anchovy", Steps = "1. Wash and chop lettuce\n2. Make dressing\n3. Toss with croutons and cheese", TotalRating = 4, RatingCount = 1 },
        new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, butter, eggs, sugar, flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold together with flour\n4. Bake 12 min at 220°C", TotalRating = 10, RatingCount = 2 },
        new() { Id = 5, Title = "Penne Arrabbiata", Category = "Pasta", Ingredients = "Penne, garlic, chili flakes, canned tomatoes, basil", Steps = "1. Sauté garlic and chili\n2. Add tomatoes and simmer\n3. Toss with cooked penne", TotalRating = 7, RatingCount = 2 },
        new() { Id = 6, Title = "Thai Green Curry", Category = "Curry", Ingredients = "Green curry paste, coconut milk, chicken, bamboo shoots, Thai basil", Steps = "1. Fry curry paste\n2. Add coconut milk\n3. Simmer chicken and vegetables", TotalRating = 8, RatingCount = 2 },
        new() { Id = 7, Title = "Greek Salad", Category = "Salads", Ingredients = "Tomatoes, cucumber, red onion, olives, feta, olive oil", Steps = "1. Chop vegetables\n2. Add olives and feta\n3. Dress with olive oil and oregano", TotalRating = 3, RatingCount = 1 },
        new() { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Mascarpone, espresso, ladyfingers, cocoa, eggs, sugar", Steps = "1. Make espresso and cool\n2. Whisk egg yolks with sugar and mascarpone\n3. Layer soaked ladyfingers and cream\n4. Dust with cocoa", TotalRating = 5, RatingCount = 1 },
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

